// frontend/src/pages/Institutions.js
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

export default function Institutions() {
  const { apiBase } = useAuth();
  const [institutions, setInstitutions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchInst = async () => {
      try {
        const res = await axios.get(`${apiBase}/institutions`);
        setInstitutions(res.data.institutions || []);
      } catch (err) {
        console.error('Error fetching institutions', err);
      } finally {
        setLoading(false);
      }
    };
    fetchInst();
  }, [apiBase]);

  if (loading) return <div>Loading institutions...</div>;

  return (
    <div style={{ maxWidth: 900, margin: '0 auto' }}>
      <h2>Institutions</h2>
      {institutions.length === 0 ? <div>No institutions found</div> : (
        <ul>
          {institutions.map(inst => (
            <li key={inst.id}>
              <strong>{inst.name || inst.userId}</strong><br/>
              {inst.description && <div>{inst.description}</div>}
              <div style={{ fontSize: 12, color: '#666' }}>ID: {inst.id}</div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
